"use strict";(globalThis.webpackChunk=globalThis.webpackChunk||[]).push([[5100],{98407(e){e.exports=JSON.parse('{"tag":{"label":"postgres","permalink":"/docs/tags/postgres","allTagsPath":"/docs/tags","count":16,"items":[{"id":"devops/postgres-ha-patroni-book/appendix-a-python-runtime","title":"Appendix A \u2014 Python Runtime Migration","description":"Comprehensive guide to migrating Patroni\'s Python runtime across production PostgreSQL HA clusters, covering dependency compatibility, migration patterns, and operational procedures.","permalink":"/docs/devops/postgres-ha-patroni-book/appendix-a-python-runtime"},{"id":"devops/postgres-ha-patroni-book/appendix-b-patroni-internals","title":"Appendix B \u2014 Patroni Internals Deep-Dive","description":"A reference-level exploration of Patroni\'s state machine, leader-election semantics across DCS backends, watchdog fencing mechanics, and DCS lease timing \u2014 the foundational knowledge needed to reason about failure modes from first principles.","permalink":"/docs/devops/postgres-ha-patroni-book/appendix-b-patroni-internals"},{"id":"devops/postgres-ha-patroni-book/foundations-postgres-ha","title":"Chapter 01 \u2014 Foundations of Postgres HA at Scale","description":"What high availability actually means at enterprise scale \u2014 failure model taxonomy, RPO/RTO primer, and why Patroni\'s DCS-backed consensus model beats every alternative.","permalink":"/docs/devops/postgres-ha-patroni-book/foundations-postgres-ha"},{"id":"devops/postgres-ha-patroni-book/patroni-architecture-dcs","title":"Chapter 02 \u2014 Patroni Architecture and the Distributed Consensus Store","description":"Deep dive into Patroni\'s architecture, DCS interaction patterns, leader election mechanics, and replication topology management for enterprise PostgreSQL HA deployments.","permalink":"/docs/devops/postgres-ha-patroni-book/patroni-architecture-dcs"},{"id":"devops/postgres-ha-patroni-book/deploying-patroni-cluster","title":"Chapter 03 \u2014 Designing & Deploying a Patroni Cluster","description":"Stand up a production-grade 3-node Patroni cluster with etcd, validate automatic failover, and tear it down cleanly \u2014 the P1 hands-on lab that anchors every subsequent chapter.","permalink":"/docs/devops/postgres-ha-patroni-book/deploying-patroni-cluster"},{"id":"devops/postgres-ha-patroni-book/configuration-best-practices","title":"Chapter 04 \u2014 Configuration Best Practices","description":"Authoritative walkthrough of patroni.yml, pg_hba.conf management, synchronous replication modes, watchdog, replication slot strategy, DCS-specific configuration, and drift detection for production Patroni clusters.","permalink":"/docs/devops/postgres-ha-patroni-book/configuration-best-practices"},{"id":"devops/postgres-ha-patroni-book/performance-tuning-ha","title":"Chapter 05 \u2014 Performance Tuning Under HA Constraints","description":"Measure and minimize the performance tax of Patroni HA \u2014 checkpointer/WAL tuning, autovacuum on standbys, connection pooling, synchronous replication latency budgets, and benchmarking under degraded mode.","permalink":"/docs/devops/postgres-ha-patroni-book/performance-tuning-ha"},{"id":"devops/postgres-ha-patroni-book/observability-monitoring","title":"Chapter 06 \u2014 Observability & Monitoring for Patroni Fleets","description":"Build a complete observability stack for Patroni fleets: required signals, Prometheus alert rules, Grafana dashboards, structured logging, and the traceability seam that feeds Chapter 07\'s troubleshooting playbooks.","permalink":"/docs/devops/postgres-ha-patroni-book/observability-monitoring"},{"id":"devops/postgres-ha-patroni-book/troubleshooting-playbooks","title":"Chapter 07 \u2014 Troubleshooting Playbooks","description":"Five symptom-keyed decision trees for on-call engineers \u2014 from observable alert to verified root cause and recovery action, each leaf traced to a Chapter 06 signal ID.","permalink":"/docs/devops/postgres-ha-patroni-book/troubleshooting-playbooks"},{"id":"devops/postgres-ha-patroni-book/backup-dr-pitr","title":"Chapter 08 \u2014 Backup, DR, and PITR at Enterprise Scale","description":"Design and operate enterprise-grade backup, disaster recovery, and point-in-time recovery for Patroni clusters \u2014 pgBackRest vs WAL-G, retention and encryption patterns, PITR under Patroni\'s timeline management, and two hands-on labs covering local PITR and cross-region DR.","permalink":"/docs/devops/postgres-ha-patroni-book/backup-dr-pitr"},{"id":"devops/postgres-ha-patroni-book/zero-downtime-operations","title":"Chapter 09 \u2014 Zero-Downtime Operations","description":"Run planned switchovers, major/minor upgrades, region drains, and certificate rotations on live Patroni clusters without dropping a single client connection \u2014 and recover cleanly when things go sideways.","permalink":"/docs/devops/postgres-ha-patroni-book/zero-downtime-operations"},{"id":"devops/postgres-ha-patroni-book/geo-distributed-patroni","title":"Chapter 10 \u2014 Geo-Distributed Patroni","description":"Design, operate, and recover geo-distributed Patroni clusters across multiple regions: quorum placement, sync/async replication boundaries, split-brain prevention, data sovereignty, latency budgets, and multi-region failure playbooks.","permalink":"/docs/devops/postgres-ha-patroni-book/geo-distributed-patroni"},{"id":"devops/postgres-ha-patroni-book/agentic-ai-autonomous-ops","title":"Chapter 11 \u2014 Agentic AI for Autonomous Patroni Operations","description":"Design, deploy, and govern AI agents that monitor, predict, self-tune, remediate, and explain Patroni cluster behaviour \u2014 with mandatory guardrails, blast-radius controls, and a documented manual fallback for every automated workflow.","permalink":"/docs/devops/postgres-ha-patroni-book/agentic-ai-autonomous-ops"},{"id":"devops/postgres-ha-patroni-book/case-studies-anti-patterns","title":"Chapter 12 \u2014 Case Studies & Anti-Patterns","description":"Real-world PostgreSQL HA failures and recovery stories with measurable outcomes, extracted patterns, and actionable anti-patterns to avoid in production environments.","permalink":"/docs/devops/postgres-ha-patroni-book/case-studies-anti-patterns"},{"id":"devops/postgres-ha-patroni-book/index","title":"Mastering PostgreSQL High Availability with Patroni","description":"Enterprise patterns for geo-distributed Postgres systems \u2014 a 2026 practitioner reference covering Patroni, etcd, Consul, observability, backup/DR, and agentic AI operations.","permalink":"/docs/devops/postgres-ha-patroni-book/"},{"id":"devops/postgres-ha-patroni-book/preface","title":"Preface \u2014 Audience, Conventions, and Version Support","description":"Audience, reading conventions, callout notation, diagram conventions, artifact ID format, and the complete version-support reference for this book.","permalink":"/docs/devops/postgres-ha-patroni-book/preface"}],"unlisted":false}}')}}]);